/**
 * KaamSaathi Support Assistant engine (server-side).
 *
 * Answers customer questions using the platform's real data and existing AI pipeline:
 *  - `parseServiceIntent` (nlp-parser) for urgency / symptoms / safety questions,
 *  - `rankProviders` (matcher) over the live provider repository,
 *  - facts published on the site (How it works, Become a Provider, Subscription plans, contact config).
 *
 * If OPENAI_API_KEY is configured (same convention as nlp-parser), replies are generated by the LLM,
 * grounded with the same facts and live provider directory. Otherwise the deterministic engine answers.
 */
import { z } from "zod";
import { db } from "@/lib/db";
import { ProviderProfile } from "@/lib/types";
import { CATEGORY_KEYWORDS, parseServiceIntent } from "./nlp-parser";
import { rankProviders } from "./matcher";
import { DEFAULT_REGION, SWAT_AREAS, isWholeRegion, normalizeArea } from "@/lib/location/swat-areas";
import { contactConfig } from "@/config/contact";

// ─── Request / response contracts ───────────────────────────────────────────

export const supportChatInputSchema = z.object({
  messages: z
    .array(
      z.object({
        role: z.enum(["user", "assistant"]),
        content: z.string().min(1).max(1000),
      })
    )
    .min(1)
    .max(30),
  language: z.enum(["en", "ur", "ps", "roman_ur"]).optional().default("en"),
  location: z.string().max(60).optional(),
});

export type SupportChatInput = z.infer<typeof supportChatInputSchema>;

export interface ChatAction {
  label: string;
  href: string;
}

export interface SupportChatReply {
  reply: string;
  actions: ChatAction[];
  suggestions: string[];
  source: "openai" | "kaamsaathi-engine";
}

// ─── Platform facts (mirrors what the site publishes) ──────────────────────

const CATEGORY_LABELS: Record<string, string> = {
  electrician: "Electrician",
  plumber: "Plumber",
  "ac-technician": "AC Technician",
  carpenter: "Carpenter",
  solar: "Solar Technician",
  painter: "Painter",
  cleaning: "Cleaning",
  appliance: "Appliance Repair",
};

const PLANS = [
  { name: "Hunar Basic", price: "Free (pilot)", note: "up to 15 quote submissions per month" },
  { name: "Ustad Pro Partner", price: "PKR 1,499 / month", note: "" },
  { name: "Swat Guild Elite", price: "PKR 3,499 / month", note: "promoted spotlight, zero commission on first 20 jobs each month" },
];

const BOOKING_STEPS = [
  "Describe your problem (type it in English, Urdu, Pashto or Roman Urdu) and mention your area in Swat.",
  "Our AI identifies the service category and urgency and suggests safety precautions.",
  "Verified Ustads (NADRA CNIC + trade proof) send itemized quotes: labour, parts and arrival time.",
  "Compare quotes side by side (experience, ratings, price) and accept the best one.",
  "Track the technician, inspect the work, then pay Cash on Completion.",
];

const REGISTRATION_REQUIREMENTS = [
  "Valid NADRA CNIC (front and back) showing an address in Swat/Malakand",
  "Vocational proof: VTI Swat / NAVTTC certificate, or a signed reference from a local hardware merchant",
  "An active Pakistani mobile number for job dispatch",
];

const DEFAULT_SUGGESTIONS = [
  "Find a plumber in Mingora",
  "How do I book a service?",
  "How do prices and quotations work?",
  "How can I register as a provider?",
  "Which areas in Swat do you serve?",
];

// ─── Helpers ────────────────────────────────────────────────────────────────

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** Whole-word match for Latin keywords (so "ac" doesn't match "contact"); substring for Urdu/Pashto. */
function hasKeyword(text: string, kw: string): boolean {
  const k = kw.toLowerCase();
  if (/^[\x00-\x7F]+$/.test(k)) return new RegExp(`(^|[^a-z0-9])${escapeRe(k)}([^a-z0-9]|$)`).test(text);
  return text.includes(k);
}

function anyOf(text: string, words: string[]): boolean {
  return words.some((w) => hasKeyword(text, w));
}

/** Category detection with word boundaries. Returns null when the message isn't about a trade. */
export function detectCategory(text: string): string | null {
  const lower = text.toLowerCase();
  let best: string | null = null;
  let bestScore = 0;
  for (const [cat, words] of Object.entries(CATEGORY_KEYWORDS)) {
    let score = 0;
    for (const w of words) if (hasKeyword(lower, w)) score += w.length > 3 ? 2 : 1;
    // Extra plain-English trade words customers commonly use
    const extra: Record<string, string[]> = {
      electrician: ["electrician", "electrical", "electricity"],
      plumber: ["plumbing", "plumbers", "water leak"],
      "ac-technician": ["ac repair", "ac service", "air conditioning", "ac technician"],
      carpenter: ["carpentry", "carpenters"],
      painter: ["painter", "painting"],
      cleaning: ["cleaner", "cleaners"],
      appliance: ["appliance", "appliances"],
      solar: ["solar panel", "solar system"],
    };
    for (const w of extra[cat] ?? []) if (hasKeyword(lower, w)) score += 2;
    if (score > bestScore) {
      bestScore = score;
      best = cat;
    }
  }
  return best;
}

/** First Swat area named in the text (incl. aliases), if any. */
export function detectArea(text: string): string | null {
  const lower = text.toLowerCase();
  const aliases: [string, string][] = [
    ["kanju", "Kanju Township"],
    ["saidu", "Saidu Sharif"],
    ["behrain", "Bahrain"],
    ["malamjabba", "Malam Jabba"],
    ["fizagat", "Fizagat"],
  ];
  for (const a of SWAT_AREAS) if (lower.includes(a.toLowerCase())) return a;
  for (const [k, v] of aliases) if (lower.includes(k)) return v;
  return null;
}

type Intent = "greeting" | "thanks" | "contact" | "register" | "pricing" | "booking" | "areas" | "about" | "payment" | null;

function detectIntent(text: string): Intent {
  const t = text.toLowerCase();
  if (anyOf(t, ["complaint", "complain", "human", "agent", "contact", "call you", "phone number", "whatsapp", "email", "shikayat", "شکایت"])) return "contact";
  if (anyOf(t, ["become a provider", "register as", "registration", "join as", "sign up as", "be a provider", "provider account", "list my", "work with you", "work with kaamsaathi", "ustad register", "verified provider", "subscription", "plan", "plans"])) return "register";
  if (anyOf(t, ["price", "prices", "pricing", "cost", "costs", "charges", "charge", "rate", "rates", "fee", "fees", "quotation", "quotations", "quote", "quotes", "kitna", "kitne", "paise", "qeemat", "قیمت", "ریٹ"])) return "pricing";
  if (anyOf(t, ["pay", "payment", "cash", "easypaisa", "jazzcash", "card"])) return "payment";
  if (anyOf(t, ["book", "booking", "hire", "how does it work", "how it works", "order", "request a service", "post a request"])) return "booking";
  if (anyOf(t, ["area", "areas", "where", "which cities", "city", "cities", "available in", "serve", "coverage", "location", "locations"])) return "areas";
  if (anyOf(t, ["what is kaamsaathi", "about kaamsaathi", "about you", "who are you", "kaamsaathi kya", "university"])) return "about";
  if (anyOf(t, ["thanks", "thank you", "shukriya", "jazakallah", "شکریہ"])) return "thanks";
  if (anyOf(t, ["hi", "hello", "salam", "assalam", "assalamualaikum", "aoa", "hey", "سلام"])) return "greeting";
  return null;
}

function categoryLabel(cat: string) {
  return CATEGORY_LABELS[cat] ?? cat;
}

/** Noun for a provider of this trade, used in sentences ("a verified AC technician"). */
const PROVIDER_NOUN: Record<string, [string, string]> = {
  electrician: ["electrician", "electricians"],
  plumber: ["plumber", "plumbers"],
  "ac-technician": ["AC technician", "AC technicians"],
  carpenter: ["carpenter", "carpenters"],
  solar: ["solar technician", "solar technicians"],
  painter: ["painter", "painters"],
  cleaning: ["cleaning provider", "cleaning providers"],
  appliance: ["appliance repair technician", "appliance repair technicians"],
};

function providerNoun(cat: string, plural = false) {
  const n = PROVIDER_NOUN[cat] ?? [cat, `${cat}s`];
  return plural ? n[1] : n[0];
}

/** "an electrician", "an AC technician", "a plumber" */
function withArticle(noun: string) {
  return `${/^[aeiou]/i.test(noun) ? "an" : "a"} ${noun}`;
}

function rateRange(providers: ProviderProfile[], cat: string) {
  const rates = providers.filter((p) => p.category === cat && p.verificationStatus === "approved").map((p) => p.hourlyRate);
  if (!rates.length) return null;
  return { min: Math.min(...rates), max: Math.max(...rates), count: rates.length };
}

function coveredCategories(providers: ProviderProfile[]) {
  return Array.from(new Set(providers.filter((p) => p.verificationStatus === "approved").map((p) => p.category)));
}

// ─── Deterministic engine ───────────────────────────────────────────────────

async function engineReply(input: SupportChatInput, providers: ProviderProfile[]): Promise<SupportChatReply> {
  const userMsgs = input.messages.filter((m) => m.role === "user");
  const current = userMsgs[userMsgs.length - 1]?.content ?? "";
  const previous = userMsgs[userMsgs.length - 2]?.content ?? "";
  const navArea = input.location && !isWholeRegion(input.location) ? input.location : null;

  const intent = detectIntent(current);
  let category = detectCategory(current);
  const area = detectArea(current) ?? navArea;

  // Follow-up like "in Kanju" / "today please" after a service request → carry the category over.
  if (!category && !intent && previous && (detectArea(current) || current.trim().split(/\s+/).length <= 4)) {
    category = detectCategory(previous);
  }

  // Provider registration wins even if a trade is mentioned ("register as electrician").
  if (intent === "register") {
    return {
      reply:
        `You can join KaamSaathi as a verified provider (Ustad):\n\n` +
        `1. Create an account and choose "Provider".\n2. Submit verification documents:\n` +
        REGISTRATION_REQUIREMENTS.map((r) => `   • ${r}`).join("\n") +
        `\n3. After admin approval you can receive requests and send quotes.\n\n` +
        `Plans: ` +
        PLANS.map((p) => `${p.name}: ${p.price}${p.note ? ` (${p.note})` : ""}`).join("; ") +
        `.`,
      actions: [
        { label: "Become a Provider", href: "/become-provider" },
        { label: "Create account", href: "/register" },
        { label: "View plans", href: "/provider/subscription" },
      ],
      suggestions: ["Which documents are required?", "How do customers pay?", "Which areas in Swat do you serve?"],
      source: "kaamsaathi-engine",
    };
  }

  if (intent === "pricing") {
    const lines: string[] = [
      `KaamSaathi doesn't use fixed prices. Verified Ustads send itemized quotes (labour, parts, arrival time), you compare them side by side and accept the one you prefer. Payment is Cash on Completion after you inspect the work.`,
    ];
    const cats = category ? [category] : coveredCategories(providers);
    const ranges = cats
      .map((c) => ({ c, r: rateRange(providers, c) }))
      .filter((x): x is { c: string; r: NonNullable<ReturnType<typeof rateRange>> } => x.r !== null);
    if (ranges.length) {
      lines.push(
        `\nIndicative hourly rates from verified providers currently listed:\n` +
          ranges
            .map(({ c, r }) => `• ${categoryLabel(c)}: PKR ${r.min === r.max ? r.min : `${r.min}–${r.max}`}/hr`)
            .join("\n") +
          `\nFinal cost depends on the job, so always compare quotes.`
      );
    } else if (category) {
      lines.push(`\nNo verified ${categoryLabel(category)} is listed yet in the pilot, so I can't show a rate. You can still post a request to receive quotes.`);
    }
    return {
      reply: lines.join("\n"),
      actions: [{ label: "Post a request for quotes", href: "/customer/request" + (category ? `?category=${category}` : "") }],
      suggestions: category ? [`Find ${withArticle(providerNoun(category))} near me`, "How do I book a service?"] : ["How do I book a service?", "Find an electrician in Saidu Sharif"],
      source: "kaamsaathi-engine",
    };
  }

  // Service request → real diagnosis + ranked providers
  if (category) {
    const parsed = await parseServiceIntent(current + (previous && !detectCategory(current) ? ` ${previous}` : ""), input.language, area ?? undefined);
    const searchArea = area ?? DEFAULT_REGION;
    const ranked = rankProviders(providers, {
      category,
      location: searchArea,
      urgency: parsed.urgency,
      keywords: parsed.detectedSymptoms,
    }).filter((m) => m.provider.verificationStatus === "approved");

    const label = categoryLabel(category);
    const where = area ? `in ${area}` : "across Swat";
    const lines: string[] = [];

    if (parsed.urgency === "emergency") {
      lines.push(`⚠️ This sounds urgent. For your safety, switch off the main supply (power/water/gas) if it's safe to do so.\n`);
    }

    if (ranked.length) {
      lines.push(
        ranked.length === 1
          ? `Here is the verified ${providerNoun(category)} ${where}:`
          : `Here are the top verified ${providerNoun(category, true)} ${where}:`
      );
      ranked.slice(0, 3).forEach(({ provider: p, distanceTier }) => {
        const covers = distanceTier === "exact_area" && area ? `covers ${area}` : `serves ${p.serviceAreas.join(", ")}`;
        lines.push(`• ${p.businessName}: ${p.rating}★ (${p.reviewCount} reviews), ~PKR ${p.hourlyRate}/hr, ${covers}${p.isAvailable ? "" : " (currently busy)"}`);
      });
      if (area && !ranked.some((m) => m.distanceTier === "exact_area")) {
        lines.push(`\nNone list ${area} directly yet, but these serve nearby areas.`);
      }
    } else {
      lines.push(`We don't have a verified ${providerNoun(category)} listed ${where} yet during the pilot. You can post a request and nearby Ustads will be notified as they join.`);
    }

    const sameCategory = parsed.category === category;
    if (sameCategory && parsed.recommendedQuestions[0]) {
      lines.push(`\nTo help the technician prepare: ${parsed.recommendedQuestions[0]}`);
    }
    if (!area) lines.push(`\nTell me your area (e.g. Mingora, Saidu Sharif, Kanju Township) for closer matches.`);

    const actions: ChatAction[] = ranked.slice(0, 2).map(({ provider: p }) => ({
      label: `View ${p.businessName.split(" ").slice(0, 2).join(" ")}`,
      href: `/providers/${p.id}?problem=${encodeURIComponent(current)}`,
    }));
    actions.push({
      label: "Get quotes",
      href: `/customer/request?category=${category}${area ? `&location=${encodeURIComponent(area)}` : ""}`,
    });

    return {
      reply: lines.join("\n"),
      actions,
      suggestions: [`How much does ${withArticle(providerNoun(category))} cost?`, "How do I book a service?", "How do I pay?"],
      source: "kaamsaathi-engine",
    };
  }

  switch (intent) {
    case "booking":
      return {
        reply: `Booking on KaamSaathi takes a few steps:\n` + BOOKING_STEPS.map((s, i) => `${i + 1}. ${s}`).join("\n") + `\n\nTell me what needs fixing and your area, and I'll find verified providers now.`,
        actions: [
          { label: "Post a request", href: "/customer/request" },
          { label: "Browse services", href: "/services" },
        ],
        suggestions: ["My AC is not cooling in Mingora", "How do prices and quotations work?", "How do I pay?"],
        source: "kaamsaathi-engine",
      };
    case "payment":
      return {
        reply: `Payment is Cash on Completion: you pay the provider directly after inspecting the finished work. The amount is the quote you accepted, so there are no surprise charges.`,
        actions: [{ label: "How it works", href: "/how-it-works" }],
        suggestions: ["How do prices and quotations work?", "How do I book a service?"],
        source: "kaamsaathi-engine",
      };
    case "areas": {
      const cats = coveredCategories(providers).map(categoryLabel);
      return {
        reply:
          `KaamSaathi is piloting in Swat District. You can choose any of these areas:\n${SWAT_AREAS.join(", ")}.\n\n` +
          (cats.length ? `Verified providers currently listed: ${cats.join(", ")}. More trades are being onboarded during the pilot.` : `Providers are being onboarded during the pilot.`) +
          (navArea ? `\n\nYour selected area is ${navArea}.` : `\n\nYou can set your area from the location menu in the top bar.`),
        actions: [{ label: "Browse services", href: "/services" }],
        suggestions: ["Find an electrician in Saidu Sharif", "Find a plumber in Kanju Township"],
        source: "kaamsaathi-engine",
      };
    }
    case "about":
      return {
        reply: `KaamSaathi is an AI-assisted marketplace for verified local services in Swat: electricians, plumbers, AC technicians, carpenters, solar and more. Every provider is checked (NADRA CNIC + trade proof), you get transparent itemized quotes, and you pay cash on completion. It's a University of Swat BS Software Engineering project, currently in its pilot stage.`,
        actions: [
          { label: "About us", href: "/about" },
          { label: "How it works", href: "/how-it-works" },
        ],
        suggestions: DEFAULT_SUGGESTIONS.slice(0, 3),
        source: "kaamsaathi-engine",
      };
    case "contact":
      return {
        reply: `You can reach the KaamSaathi team on WhatsApp at ${contactConfig.phoneDisplay} (complaints and support), or email ${contactConfig.email}. You can also tell me the issue here and I'll try to help right away.`,
        actions: [
          { label: "WhatsApp us", href: contactConfig.whatsappUrl },
          { label: "Contact page", href: "/contact" },
        ],
        suggestions: ["How do I book a service?", "How do prices and quotations work?"],
        source: "kaamsaathi-engine",
      };
    case "thanks":
      return { reply: `You're welcome! Is there anything else I can help you with?`, actions: [], suggestions: DEFAULT_SUGGESTIONS.slice(0, 3), source: "kaamsaathi-engine" };
    case "greeting":
      return {
        reply: `Wa alaikum assalam! 👋 I can find verified service providers in Swat, explain booking and pricing, or help you register as a provider. What do you need?`,
        actions: [],
        suggestions: DEFAULT_SUGGESTIONS,
        source: "kaamsaathi-engine",
      };
  }

  return {
    reply:
      `I'm not sure I understood that. I can help you:\n• find verified electricians, plumbers, AC technicians, carpenters and more in Swat\n• understand booking, quotations and payment\n• register as a provider\n\nTry describing the problem, e.g. "Bathroom tap leaking in Mingora".`,
    actions: [],
    suggestions: DEFAULT_SUGGESTIONS,
    source: "kaamsaathi-engine",
  };
}

// ─── LLM path (optional, uses the project's existing OPENAI_API_KEY convention) ─

function systemPrompt(providers: ProviderProfile[], location?: string) {
  const directory = providers
    .filter((p) => p.verificationStatus === "approved")
    .map((p) => `- ${p.businessName} | ${categoryLabel(p.category)} | ${p.rating}★ (${p.reviewCount}) | PKR ${p.hourlyRate}/hr | areas: ${p.serviceAreas.map(normalizeArea).join(", ")} | ${p.isAvailable ? "available" : "busy"}`)
    .join("\n");
  return `You are the KaamSaathi Support Assistant, a friendly customer-support agent for KaamSaathi, a verified local home-services marketplace piloting in Swat District, Pakistan.
Reply in the customer's language (English, Urdu, Pashto or Roman Urdu). Be concise (max ~120 words), practical, and never invent providers, prices or policies.

FACTS
- Areas: ${SWAT_AREAS.join(", ")} (Swat District). Customer's selected area: ${location || "Swat (whole district)"}.
- Booking: ${BOOKING_STEPS.join(" ")}
- Pricing: no fixed prices; verified providers send itemized quotes; customer compares and accepts; Cash on Completion.
- Provider registration: requirements: ${REGISTRATION_REQUIREMENTS.join("; ")}. Plans: ${PLANS.map((p) => `${p.name} ${p.price}`).join("; ")}. Pages: /become-provider, /register.
- Support: WhatsApp ${contactConfig.phoneDisplay}, email ${contactConfig.email}.
- For emergencies (sparks, burning smell, gas, flooding) first advise switching off the main supply.

VERIFIED PROVIDER DIRECTORY (only recommend from this list; if none fit, say so and suggest posting a request at /customer/request):
${directory || "(none listed yet)"}`;
}

async function llmReply(input: SupportChatInput, providers: ProviderProfile[]): Promise<string | null> {
  const key = process.env.OPENAI_API_KEY;
  if (!key || !key.startsWith("sk-")) return null;
  try {
    const res = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        temperature: 0.4,
        max_tokens: 400,
        messages: [
          { role: "system", content: systemPrompt(providers, input.location) },
          ...input.messages.slice(-12).map((m) => ({ role: m.role, content: m.content })),
        ],
      }),
      signal: AbortSignal.timeout(20000),
    });
    if (!res.ok) return null;
    const data = await res.json();
    const text: unknown = data?.choices?.[0]?.message?.content;
    return typeof text === "string" && text.trim() ? text.trim() : null;
  } catch {
    return null;
  }
}

// ─── Entry point ────────────────────────────────────────────────────────────

export async function generateSupportReply(input: SupportChatInput): Promise<SupportChatReply> {
  const providers = await db.getProviderProfiles();
  // The engine always runs: it supplies the action links/suggestions, and is the answer when no LLM is configured.
  const engine = await engineReply(input, providers);
  const llm = await llmReply(input, providers);
  return llm ? { ...engine, reply: llm, source: "openai" } : engine;
}
